import json, random
random.seed(42)
qs=[]

def add(subject, unit, q, correct, wrong, level=1, explanation=''):
    opts=[correct]+wrong[:3]
    # 3 or 4 choices depending on supplied wrong count
    random.shuffle(opts)
    qs.append({
        'id': f'q{len(qs)+1:03d}', 'subject':subject, 'unit':unit,
        'question':q, 'choices':opts, 'answer':opts.index(correct),
        'level':level, 'explanation': explanation or f'正解は「{correct}」です。'
    })

